@Algebra.peutt_bind_tau
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI) (A B : Type) (t : PTreeDefinition.ptree E MN A)
         (k : A -> PTreeDefinition.ptree E MN B),
       @PEutt.peutt E MN MF FI FC MX FO B B (@eq B)
         (@PTreeDefinition.PTree.bind E MN A B
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.TauF E MN A (PTreeDefinition.ptree E MN A) t
            |} k)
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.TauF E MN B (PTreeDefinition.ptree E MN B)
               (@PTreeDefinition.PTree.bind E MN A B t k)
         |}

