         (FO : @Omega.SemanticOmega MF FI) (A B X : Type) (e : E X)
         (h : X -> PTreeDefinition.ptree E MN A) (k : A -> PTreeDefinition.ptree E MN B),
       @PEutt.peutt E MN MF FI FC MX FO B B (@eq B)
         (@PTreeDefinition.PTree.bind E MN A B
            {|
