@Algebra.peutt_sample_bind
     : forall (E MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall MX : Mixed.MixedMeasure MN MF,
       @Mixed.MixedMeasureLaws MN MF NI FI MX ->
       forall FO : @Omega.SemanticOmega MF FI,
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Mixed.MixedMeasureOmegaLaws MN MF NI FI MX FO ->
       forall (X A : Type) (mu : MN X) (k : X -> PTreeDefinition.ptree E MN A),
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A)
         (@PTreeDefinition.PTree.bind E MN X A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.ProbF E MN X (PTreeDefinition.ptree E MN X) X mu
                  (fun x : X =>
                   {|
                     PTreeDefinition._observe :=
                       @PTreeDefinition.RetF E MN X (PTreeDefinition.ptree E MN X) x
                   |})
            |} k)
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN A (PTreeDefinition.ptree E MN A) X mu k
         |}

@Algebra.peutt_prob_map
     : forall (E MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall MX : Mixed.MixedMeasure MN MF,
       @Mixed.MixedMeasureLaws MN MF NI FI MX ->
       forall FO : @Omega.SemanticOmega MF FI,
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Mixed.MixedMeasureOmegaLaws MN MF NI FI MX FO ->
       @Mixed.MixedMeasureUnitLaws MN MF NI FI MX ->
       @Mixed.MixedMeasureNodeBindLaws MN MF NI FI MX ->
       forall (X Y A : Type) (mu : MN X) (f : X -> Y) (k : Y -> PTreeDefinition.ptree E MN A),
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A)
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN A (PTreeDefinition.ptree E MN A) X mu
               (fun x : X => k (f x))
         |}
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN A (PTreeDefinition.ptree E MN A) Y
               (@Measure.sem_bind MN NI X Y mu (fun x : X => @Measure.sem_ret MN NI Y (f x))) k
         |}

