       (forall (c : nat -> M A) (out bound : M A),
        @Omega.sem_lub M MI MO A c out ->
        (forall n : nat, @Omega.sem_le M MI MO A (c n) bound) -> @Omega.sem_le M MI MO A out bound) ->
       forall X : I -> M A,
       (forall i : I, @KleisliIteration.sem_iter M MI MO I A K i (X i)) ->
       (forall i : I,
        @Omega.sem_le M MI MO A (@KleisliIteration.sem_iter_step M MI I A K X i) (X i) /\
        @Omega.sem_le M MI MO A (X i) (@KleisliIteration.sem_iter_step M MI I A K X i)) /\
       (forall Y : I -> M A,
        (forall i : I,
         @Omega.sem_le M MI MO A (@KleisliIteration.sem_iter_step M MI I A K Y i) (Y i)) ->
        forall i : I, @Omega.sem_le M MI MO A (X i) (Y i))

